// SLAPSHOT HQ — worker v1
// Daily NHL goal scorer board. Skaters only.
// Data: board.json built daily in mattgrnr/hq-data; live goals from the NHL scoreboard.

const BOARD_URL = "https://raw.githubusercontent.com/mattgrnr/hq-data/main/nhl/board.json";
const LIVE_URL = "https://api-web.nhle.com/v1/score/";

const SITE_ORIGINS = [
  "https://slapshot-hq.com",
  "https://www.slapshot-hq.com",
];

function fromSite(request) {
  if (request.headers.get("X-Slapshot") === "1") return true;
  const o = request.headers.get("Origin") || "";
  const r = request.headers.get("Referer") || "";
  if (SITE_ORIGINS.some(s => o === s || r.startsWith(s))) return true;
  if (o.endsWith(".workers.dev") || r.includes(".workers.dev/")) return true;
  return false;
}

const OG_PNG = "";
const TOUCH_ICON = "";
const FAVICON = "";
function pngResponse(b64data) {
  const bin = atob(b64data);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, { headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400" } });
}
function serveAsset(path) {
  if (path === "/og.png") return pngResponse(OG_PNG);
  if (path === "/apple-touch-icon.png") return pngResponse(TOUCH_ICON);
  if (path === "/favicon.png" || path === "/favicon.ico") return pngResponse(FAVICON);
  return null;
}

